801	void LiaStarExtension::lazyHilbert(Node literal, Subsolver& sub)
802	{
803	  // One lazy refinement round for `literal`. Ask the subsolver for a model in a
804	  // region of p not yet covered by a cone, read off the convex cell containing
805	  // it, turn it into a cone, and emit a (tentative or final) reduction lemma.
806	  Node variables = literal[0][0];
807	  Trace("liastar-lazy") << "lazyHilbert::variables:" << variables << std::endl;
808	
809	  traceSmtPreamble(variables);
810	
811	  // Check the subsolver and read off the disjunct (the cell of the predicate)
812	  // containing the model. The subsolver already has the predicate and the
813	  // negations of all previously discovered cone-disjuncts asserted, so the
814	  // model lies in a region of the predicate not yet covered by any cone.
815	  Node disjunct = LiaStarUtils::getDisjunct(
816	      sub.base, sub.from, sub.to, &d_env, sub.engine.get());
817	  // `getDisjunct` returns false when no region of `formula` is left uncovered,
818	  // i.e. every disjunct of the predicate already has a cone. At that point the
819	  // cone encoding is exact and we can assert the full equivalence.
820	  bool complete = disjunct == d_false;
821	  // The disjunct is a conjunction of arithmetic facts in the subsolver's
822	  // normal form, which can represent strict inequalities as negations (e.g.
823	  // (not (>= a b))). Normalize away the negations before building the matrix.
824	  disjunct = LiaStarUtils::removeItesAndNots(disjunct, &d_env);
825	
826	  Trace("liastar-ext") << "disjunct: " << disjunct << std::endl;
827	
828	  std::pair<std::vector<std::string>, Node> pair =
829	      LiaStarUtils::getMatrix(variables, disjunct);
830	
831	  Trace("liastar-ext") << "disjunct: " << disjunct << std::endl;
832	
833	  // Add the cone for the current disjunct to `d_lazyCones` and get the starLia
834	  // constraints over the whole list of cones so far. `getStarConstraints` only
835	  // computes the per-cone constraints (and fresh skolems) for cones not yet
836	  // processed, reusing the constraints computed in previous calls. When
837	  // `complete`, `disjunct` is the (infeasible) false constraint, so `addCone`
838	  // adds no new cone and `getStarConstraints` just rebuilds the sum constraints
839	  // over the cones found so far.
840	  addCone(literal, pair);
841	  std::vector<Node> starConstraints = getStarConstraints(literal);
842	  Trace("liastar-ext") << "starConstraints: " << std::endl
843	                       << toString(starConstraints) << std::endl;
844	
845	  Node star = d_nm->mkNode(Kind::AND, starConstraints);
846	
847	  Trace("liastar-ext") << d_lazyCones[literal[0]].size()
848	                       << " cones for lambda:  " << literal[0] << std::endl;
849	
850	  star = rewrite(star);
851	  // Remember the last computed starLia under-approximation for `literal`; the
852	  // model-value check in checkFullEffort uses it to skip refinement when the
853	  // current model already satisfies it.
854	  d_lastStarLia[literal] = star;
855	
856	  // Deactivate the guard from the previous refinement round for this literal:
857	  // its under-approximation is a subset of the current `star`, so the tentative
858	  // equivalence it guarded is subsumed. Asserting `(not g_old)` makes that
859	  // guarded lemma vacuous, so the solver does not have to satisfy several
860	  // (mutually constraining) guarded equivalences at once. Sound because `g_old`
861	  // is fresh.
862	  auto guardIt = d_lastGuard.find(literal);
863	  if (guardIt != d_lastGuard.end())
864	  {
865	    Node deactivate = guardIt->second.notNode();
866	    if (d_proofGen != nullptr)
867	    {
868	      d_proofGen->registerGuardDeactivate(deactivate);
869	    }
870	    d_im.addPendingLemma(
871	        deactivate, InferenceId::ARITH_LIA_STAR_SPLIT, d_proofGen.get());
872	    d_lastGuard.erase(guardIt);
873	  }
874	
875	  Node lemma;
